import itertools
import math

def is_cable_car_valid(sol, n):
    limit = sol[0]
    dct = {}
    topmost = 0
    for i in range(1, n*n + 1):
        dct[i] = math.inf
        element = i
        for idx in range(len(sol)):
            peek = sol[idx]
            if peek >= 0 and element <= limit and dct[element] == math.inf:
                dct[element] = -peek
                if topmost < -peek:
                    topmost = -peek
        limit += sol[n * n + idx + 1]
        for idx in reversed(range(len(sol))):
            scene = sol[idx]
            if scene >= 0 and element > limit and dct[element] == math.inf:
                dct[element] = -scene
                if topmost < -scene:
                    topmost = -scene
                for idx2 in range(idx):
                    scene2 = sol[idx2]
                    if scene2 >= 0 and (-scene2 == -scene) and dct[abs(scene)] == math.inf:
                        dct[abs(scene)] = -scene2
                        if topmost < -scene2:
                            topmost = -scene2
    chk = False
    for i in range(1, n*n+1):
        if dct[i] == math.inf:
            for j in range(i, n*n+1):
                if dct[j] == math.inf \
                    or (dct[j] < 0 and dct[i] == j) \
                    or (dct[j] > 0 and dct[i] == -j):
                    chk = True
    return chk

def main():
    n = 2
    total_sol = []
    while True:
        chk = False
        sols = [i for i in range(n*n+1)]
        while True:
            limit = math.inf
            ind = 0
            for s in itertools.combinations(sols, n*n):
                subind = -1
                sol = []
                for t in s:
                    if subind == t:
                        continue
                    ind += 1
                    if sol:
                        currs = sol[-1]
                        if currs <= t:
                            subind = t
                            sol += [-t]
                        else:
                            currs -= -t
                    else:
                        subind = t
                        sol += [-t]
                if subind == -1:
                    continue
                sols[s] = sol
                if len(sol) == 0: 
                    continue
                limit = min(limit, max(sol))
                chk = is_cable_car_valid(sol, n)
                if chk:
                    total_sol += sol
                    break
            if chk:
                print(f"{n} is {len(total_sol)}")
                return len(total_sol)
        n += 1

print(main())
